/// I-cell `c` given `v`, its one write; the tasks waiting for it run, in
/// the order they began to wait (`icell_put`).
pub fn cell_put_x(c: i64, v: i64) -> i64 {
    if not(is_kind_p(c, k_icell())) {
        trap_x(str_lit("expected an i-cell"));
        0i64
    } else if not(i64_eq(slot_of(c, 2i64), v_false())) {
        trap_x(str_lit("an i-cell written twice"));
        0i64
    } else {
        let ws = slot_of(c, 4i64);
        slot_set_x(c, 3i64, v);
        slot_set_x(c, 2i64, v_true());
        slot_set_x(c, 4i64, v_null());
        pushed_each_x(reversed_onto_x(ws, v_null()));
        v_unit()
    }
}

pub fn make_mailbox_x() -> i64 {
    let m = make_bloblet_x(k_mailbox(), 3i64, 0i64, true, false);
    slot_set_x(m, 2i64, v_null());
    slot_set_x(m, 3i64, v_null());
    slot_set_x(m, 4i64, v_false());
    m
}

pub fn mailbox_ready_p(m: i64) -> bool {
    (is_pair_p(slot_of(m, 2i64)) || is_pair_p(slot_of(m, 3i64)))
}

/// The message copied, at the back; the receiver, if it waits, run.
pub fn mailbox_put_x(m: i64, v: i64) -> i64 {
    let msg = copy_within_x(v);
    slot_set_x(m, 3i64, cons_x(msg, slot_of(m, 3i64)));
    if i64_eq(slot_of(m, 4i64), v_false()) {
        ()
    } else {
        let w = slot_of(m, 4i64);
        slot_set_x(m, 4i64, v_false());
        queue_push_x(w)
    };
    v_unit()
}

/// The oldest message, taken.
pub fn mailbox_take_x(m: i64) -> i64 {
    let front = if is_pair_p(slot_of(m, 2i64)) {
        slot_of(m, 2i64)
    } else {
        let f = reversed_onto_x(slot_of(m, 3i64), slot_of(m, 2i64));
        slot_set_x(m, 3i64, v_null());
        f
    };
    if not(is_pair_p(front)) {
        slot_set_x(m, 2i64, v_null());
        trap_x(str_lit("%fx26-sched: an empty mailbox taken from"));
        0i64
    } else {
        slot_set_x(m, 2i64, pair_cdr(front));
        pair_car(front)
    }
}

// Timers: each waker run once the clock reaches its time.
pub fn timer_add_x(t: i64, w: i64) -> i64 {
    if i64_gt_eq(clock(), t) {
        queue_push_x(w)
    } else {
        st_cons_x(s_timers(), cons_x(fix(if i64_gt(t, fix_max()) {
            fix_max()
        } else if i64_lt(t, fix_min()) {
            fix_min()
        } else {
            t
        }), w))
    };
    v_unit()
}

pub fn due_in_p(l: i64, now: i64) -> bool {
    (is_pair_p(l) && (i64_lt_eq(fix_val(pair_car(pair_car(l))), now) || due_in_p(pair_cdr(l), now)))
}

/// Whether a timer is due; the clock not read if none is set.
pub fn timer_due_p() -> bool {
    let ts = st(s_timers());
    (is_pair_p(ts) && due_in_p(ts, clock()))
}

pub fn timers_earliest(mut l: i64, mut e: i64) -> i64 {
    loop {
        if is_pair_p(l) {
            (l, e) = (pair_cdr(l), {
                let t = fix_val(pair_car(pair_car(l)));
                if i64_lt(t, e) {
                    t
                } else {
                    e
                }
            });
            continue;
        } else {
            return e;
        }
    }
}

/// Timer `e` in list `l`, sorted by time, after those of its own.
pub fn timer_by_time_x(e: i64, l: i64) -> i64 {
    if not(is_pair_p(l)) {
        cons_x(e, v_null())
    } else if i64_lt(fix_val(pair_car(e)), fix_val(pair_car(pair_car(l)))) {
        cons_x(e, l)
    } else {
        cons_x(pair_car(l), timer_by_time_x(e, pair_cdr(l)))
    }
}

pub fn timers_sorted_x(mut l: i64, mut acc: i64) -> i64 {
    loop {
        if is_pair_p(l) {
            (l, acc) = (pair_cdr(l), timer_by_time_x(pair_car(l), acc));
            continue;
        } else {
            return acc;
        }
    }
}

pub fn wakers_pushed_x(mut l: i64) -> () {
    loop {
        if is_pair_p(l) {
            queue_push_x(pair_cdr(pair_car(l)));
            l = pair_cdr(l);
            continue;
        } else {
            return ();
        }
    }
}

pub fn heap_cars(xs: List<i64>) -> List<i64> {
    if null_p(xs) {
        nil::<i64>()
    } else {
        kayak_rt::heap_cons(pair_car(car(xs)), heap_cars(cdr(xs)))
    }
}

/// When no task can run and the first waits: `#f` if no timer is set;
/// else, having slept until the earliest (if `sleep`), each timer due
/// taken, its waker run, in the order of their times, and `#t`. Tier 1
/// reads no standard input: a waker waiting for it is not yet (C122).
pub fn timers_wait_x(sleep: bool) -> i64 {
    let ts = st(s_timers());
    if is_pair_p(st(s_stdin())) {
        trap_x(str_lit("tier 1: the standard input waited for, not yet as Fixpt (C122)"));
        v_false()
    } else if not(is_pair_p(ts)) {
        v_false()
    } else {
        if sleep {
            sleep_until(timers_earliest(ts, fix_max()))
        } else {
            ()
        };
        let now = clock();
        st_set_x(s_timers(), without_x(ts, 5i64, now));
        wakers_pushed_x(timers_sorted_x(reversed_onto_x(only_x(ts, 5i64, now), v_null()), v_null()));
        v_true()
    }
}

// Tasks the scheduler keeps.
/// The first entry's of `l` for `t`, its value, or `#f`.
pub fn assq_cdr(mut l: i64, mut t: i64) -> i64 {
    loop {
        if not(is_pair_p(l)) {
            return v_false();
        } else if i64_eq(pair_car(pair_car(l)), t) {
            return pair_cdr(pair_car(l));
        } else {
            l = pair_cdr(l);
            continue;
        }
    }
}

/// The group task `t` is of, or `#f`.
pub fn group_of(t: i64) -> i64 {
    if sched_p() {
        assq_cdr(st(s_groups()), t)
    } else {
        v_false()
    }
}

/// What the scheduler kept of task `t`, ended (`forget_task`).
pub fn forget_task_x(t: i64) -> () {
    st_set_x(s_cancelled(), without_x(st(s_cancelled()), 0i64, t));
    st_set_x(s_groups(), without_x(st(s_groups()), 1i64, t));
    st_set_x(s_monitors(), without_x(st(s_monitors()), 1i64, t));
    st_set_x(s_parents(), without_x(st(s_parents()), 3i64, t));
    st_set_x(s_waiting(), without_x(st(s_waiting()), 1i64, t))
}

pub fn cancelled_p(t: i64) -> bool {
    heap_member_p(st(s_cancelled()), t)
}

/// Each cancelled task that waits, `(task . stop)`, taken from those that
/// wait (`REAP`).
pub fn reaped_x() -> i64 {
    let cs = st(s_cancelled());
    let ws = st(s_waiting());
    let them = only_x(ws, 4i64, cs);
    st_set_x(s_waiting(), without_x(ws, 4i64, cs));
    them
}

// Preemption and failure, for the machine.
/// Whether the scheduler would have the current task preempted here: 0,
/// no; 1, yes; 2, in a task, if the scheduler's prompt is on the
/// machine's stack, which the machine asks only then, as walking its
/// stack costs (`wanted`, its `reachable` called last).
pub fn wanted_how_x() -> i64 {
    if (quiet_p() || take_grace_x()) {
        0i64
    } else if i64_eq(get(task_now()), 0i64) {
        if ((is_pair_p(st(s_front())) || is_pair_p(st(s_back())) || is_pair_p(st(s_parked())) || timer_due_p()) && i64_eq(fix_val(st(s_running())), 0i64)) {
            1i64
        } else {
            0i64
        }
    } else if i64_eq(st(s_tag()), v_false()) {
        0i64
    } else {
        2i64
    }
}

/// Whether the scheduler would have the current task preempted here; in
/// a task, `reach` says whether the scheduler's prompt is on the
/// machine's stack (`wanted`).
pub fn wanted_x(reach: bool) -> bool {
    let w = wanted_how_x();
    (i64_eq(w, 1i64) || (i64_eq(w, 2i64) && reach))
}

/// The scheduler's prompt tag, or `#f`.
pub fn sched_tag() -> i64 {
    if sched_p() {
        st(s_tag())
    } else {
        v_false()
    }
}

/// At a poll whose slice is spent: as `wanted-how!`, 0 too if there is
/// no scheduler's `preempt` to call (`preempt_due_with`).
pub fn preempt_wanted_x() -> i64 {
    if (sched_p() && is_kind_p(st(s_preempt()), k_closure())) {
        wanted_how_x()
    } else {
        0i64
    }
}

/// The scheduler's `preempt`, wanted, for the machine to call at the
/// poll, the task then quiet until it has.
pub fn preempt_due_x() -> i64 {
    quiet_enter_x();
    st(s_preempt())
}

/// `gs`, with every group inside one of them (`BRANCH_GROUP`).
pub fn groups_within(mut gs: List<i64>) -> List<i64> {
    loop {
        let more = kept_of(heap_cars(kept_of(heap_items(st(s_parents())), lambda1(move |e: i64| {
            not(i64_in_p(gs, pair_cdr(e)))
        }))), lambda1(move |g: i64| {
            i64_in_p(gs, g)
        }));
        if null_p(more) {
            return gs;
        } else {
            gs = onto_new(gs, more);
            continue;
        }
    }
}

pub fn onto_new(mut gs: List<i64>, mut xs: List<i64>) -> List<i64> {
    loop {
        if null_p(xs) {
            return gs;
        } else if i64_in_p(gs, car(xs)) {
            xs = cdr(xs);
            continue;
        } else {
            (gs, xs) = (kayak_rt::heap_cons(car(xs), gs), cdr(xs));
            continue;
        }
    }
}

pub fn last_monitor(mut l: i64, mut g: i64, mut found: i64) -> i64 {
    loop {
        if not(is_pair_p(l)) {
            return found;
        } else if i64_eq(pair_car(pair_car(l)), g) {
            (l, found) = (pair_cdr(l), pair_cdr(pair_car(l)));
            continue;
        } else {
            l = pair_cdr(l);
            continue;
        }
    }
}

pub fn pushed_cancelled_x(mut ts: List<i64>) -> () {
    loop {
        if null_p(ts) {
            return ();
        } else {
            st_cons_x(s_cancelled(), car(ts));
            ts = cdr(ts);
            continue;
        }
    }
}

pub fn all_quiet_left_x() -> () {
    loop {
        if quiet_p() {
            quiet_leave_x();
            continue;
        } else {
            return ();
        }
    }
}

/// The current task failed with `message`: if it is of a monitored group
/// and the scheduler's prompt is on the stack (`reach`), the rest of the
/// group cancelled, the failure kept for the scheduler, and the prompt's
/// tag, to abort to; else `#f`, the failure the form's (`task_failed`).
pub fn task_failed_x(message: Str, reach: bool) -> i64 {
    let cur = fix(get(task_now()));
    let g = group_of(cur);
    let mon = if i64_eq(g, v_false()) {
        v_false()
    } else {
        last_monitor(st(s_monitors()), g, v_false())
    };
    if (i64_eq(get(task_now()), 0i64) || i64_eq(mon, v_false()) || i64_eq(st(s_tag()), v_false()) || not(reach) || not(i64_eq(st(s_failure()), v_false()))) {
        v_false()
    } else {
        let gs = groups_within(kayak_rt::heap_cons(g, kayak_rt::nil()));
        pushed_cancelled_x(heap_cars(kept_of(heap_items(st(s_groups())), lambda1(move |e: i64| {
            (not(i64_in_p(gs, pair_cdr(e))) || i64_eq(pair_car(e), cur))
        }))));
        st_set_x(s_failure(), cons_x(make_string_x(message), mon));
        all_quiet_left_x();
        st(s_tag())
    }
}

